gGH(){return"\u0645\u0624\u0631\u0634\u0641\u0629"},
gGJ(){return"\u0627\u0644\u0643\u0644"},
gGL(){return"\u0639\u0631\u0636 \u0627\u0644\u0645\u0632\u064a\u062f"},
vP(a){return"\u062a\u0645 \u0639\u0631\u0636 "+a+" \u0645\u0644\u0641\u064b\u0627 \u2014 \u0648\u0647\u0646\u0627\u0643 \u0627\u0644\u0645\u0632\u064a\u062f. \u0636\u064a\u0651\u0642 \u0627\u0644\u0646\u0637\u0627\u0642 \u0623\u0648 \u062d\u0645\u0651\u0644 \u0627\u0644\u0628\u0627\u0642\u064a."},
gvO(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0644\u0641 \u0642\u064a\u062f \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629. \u0627\u0644\u0645\u0644\u0641\u0627\u062a \u0627\u0644\u0645\u063a\u0644\u0642\u0629 \u0645\u0648\u062c\u0648\u062f\u0629 \u0636\u0645\u0646 \xab\u0645\u0624\u0631\u0634\u0641\u0629\xbb."},
gFZ(){return"\u0645\u062a\u0627\u0628\u0639\u0629"},
gEJ(){return"\u0625\u063a\u0644\u0627\u0642"},
gLs(){return"\u0644\u062d\u0638\u0629\u2026"},
gFg(){return"\u0623\u0634\u062e\u0627\u0635 \u0642\u062f \u062a\u0643\u0648\u0646 \u0644\u062f\u064a\u0647\u0645 \u0623\u062e\u0628\u0627\u0631\u0643\u060c \u0623\u0648 \u0642\u062f \u062a\u0643\u0648\u0646 \u0639\u0646\u062f\u0647\u0645."},
gFb(){return"\u0623\u0634\u062e\u0627\u0635 \u0645\u0648\u062b\u0648\u0642\u0648\u0646"},
gFc(){return"\u062d\u0645\u0627\u0629 (\u064a\u062a\u0644\u0642\u0648\u0646 \u0627\u0644\u062a\u0646\u0628\u064a\u0647\u0627\u062a)"},
gFa(){return"\u0627\u0644\u0623\u0648\u0635\u064a\u0627\u0621 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0648\u0646"},
Fr(a){return a+" \u062f\u0639\u0648\u0629 \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u0631\u062f \u2014 \u062a\u0634\u063a\u0644 \u0645\u0643\u0627\u0646\u0647\u0627."},
gFs(){return"\u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u0631\u062f"},
gFt(){return"\u062d\u0627\u0645\u064d"},
gFp(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u062a\u0635\u0627\u0644."},
gFh(){return"\u062f\u0639\u0648\u0629 \u0634\u062e\u0635"},
gva(){return"\u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0645\u0643\u062a\u0645\u0644\u0629 (10 \u0623\u0634\u062e\u0627\u0635)"},
